// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;

import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/** Regression coverage for unused-VALUES elimination preserving a Janino-lowerable flat join. */
class LmdbNativeSlotPlanIdentityTest {

	@Test
	void singletonIsARealRelationalIdentity() {
		SlotPlan values = SlotPlan.values(new ValuesRow[] {
				new ValuesRow(new int[] { 0 }, new long[] { 11L })
		});

		assertThat(SlotPlan.join(SlotPlan.singleton(), values)).isSameAs(values);
		assertThat(SlotPlan.join(values, SlotPlan.singleton())).isSameAs(values);
	}

	@Test
	void eliminatingUnusedValuesDoesNotLeaveANestedJoinBarrier() {
		SlotPlan left = SlotPlan.values(new ValuesRow[] {
				new ValuesRow(new int[] { 0 }, new long[] { 11L })
		});
		SlotPlan right = SlotPlan.values(new ValuesRow[] {
				new ValuesRow(new int[] { 1 }, new long[] { 22L })
		});

		SlotPlan plan = SlotPlan.join(left, SlotPlan.join(right, SlotPlan.singleton()));

		assertThat(plan).isInstanceOf(MultiJoinPlan.class);
		assertThat(((MultiJoinPlan) plan).children)
				.containsExactly(left, right)
				.doesNotContain(SingletonPlan.INSTANCE);
	}

	@Test
	void orderingAndAttemptBorrowCannotResurrectTheIdentityBarrier() {
		SlotPlan values = SlotPlan.values(new ValuesRow[] {
				new ValuesRow(new int[] { 0 }, new long[] { 11L })
		});
		SlotPlan stale = new JoinPlan(SingletonPlan.INSTANCE, values);

		NativeTupleDistinctPlan ordered = LmdbNativeOrderPlanner.tuple(stale, new int[] { 0 }, null);
		assertThat(ordered.arg).isSameAs(values);

		NativeFilterLease lease = new NativeFilterLease();
		try {
			assertThat(lease.borrow(stale)).isSameAs(values);
		} finally {
			lease.discard();
		}
	}

	@Test
	void lateralAssuresBindingsFromBothInnerArms() {
		SlotPlan left = SlotPlan.values(new ValuesRow[] {
				new ValuesRow(new int[] { 0 }, new long[] { 11L })
		});
		SlotPlan right = SlotPlan.values(new ValuesRow[] {
				new ValuesRow(new int[] { 1 }, new long[] { 22L })
		});

		assertThat(SlotPlan.assuredMask(new LateralPlan(left, right, 1L))).isEqualTo(0b11L);
	}

	@Test
	void lateralKeepsOneLexicalInputMaskAcrossRightRows() throws Exception {
		NativeSlotLayout layout = layout(2);
		RowState row = new RowState(null, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, NativeLmdbQuerySource.UNKNOWN_ID);
		row.recomputeBoundMask();
		SlotPlan left = SlotPlan.values(new ValuesRow[] {
				new ValuesRow(new int[] { 0 }, new long[] { 11L })
		});
		SlotPlan right = new SlotPlan() {
			@Override
			public RowCursor open(RowState state) {
				assertThat(state.lexicalInputMask).isZero();
				return new RowCursor() {
					int emitted;

					@Override
					public boolean next() {
						assertThat(state.lexicalInputMask).isZero();
						if (emitted == 2) {
							return false;
						}
						state.replaceSlot(1, 21L + emitted++);
						return true;
					}

					@Override
					public void close() {
					}
				};
			}

			@Override
			public long producedMask() {
				return 1L << 1;
			}
		};

		try (RowCursor lateral = new LateralPlan(left, right, 0L).open(row)) {
			assertThat(lateral.next()).isTrue();
			assertThat(row.slots).containsExactly(11L, 21L);
			assertThat(lateral.next()).isTrue();
			assertThat(row.slots).containsExactly(11L, 22L);
			assertThat(lateral.next()).isFalse();
		}
	}

	private static NativeSlotLayout layout(int slotCount) {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		for (int slot = 0; slot < slotCount; slot++) {
			names.put("v" + slot, slot);
		}
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(new ArrayList<>(names.keySet()));
		return layout;
	}

}
